  "ref": "職業安全衛生管理辦法§第8條",
  "law": "《職業安全衛生管理辦法》第8條：職業安全衛生人員因故未能執行職務時，雇主應即指定適當代理人。其代理期間不得超過三個月。\n\n勞工人數在三十人以上之事業單位，其職業安全衛生人員離職時，應即報當地勞動檢查機構備查。",
