  "law": "《高架作業勞工保護措施標準》第3條：本標準所稱高架作業，係指雇主使勞工從事之下列作業：\n\n一、未設置平台、護欄等設備而已採取必要安全措施，其高度在二公尺以上者。\n\n二、已依規定設置平台、護欄等設備，並採取防止墜落之必要安全措施，其高度在五公尺以上者。\n\n前項高度之計算方式依下列規定：\n\n一、露天作業場所，自勞工站立位置，半徑三公尺範圍內最低點之地面或水面起至勞工立足點平面間之垂直距離。\n\n二、室內作業或儲槽等場所，自勞工站立位置與地板間之垂直距離。",
