  "ref": "高溫作業勞工作息時間標準§第6條",
  "law": "《高溫作業勞工作息時間標準》第6條：勞工於操作中須接近黑球溫度五十度以上高溫灼熱物體者，雇主應供給身體熱防護設備並使勞工確實使用。\n\n前項黑球溫度之測定位置為勞工工作時之位置。",
