  "ref": "營業秘密法§第2條",
  "law": "《營業秘密法》第2條：本法所稱營業秘密，係指方法、技術、製程、配方、程式、設計或其他可用於生產、銷售或經營之資訊，而符合左列要件者：\n\n一、非一般涉及該類資訊之人所知者。\n\n二、因其秘密性而具有實際或潛在之經濟價值者。\n\n三、所有人已採取合理之保密措施者。",
