 "s-114-2颱風延期考區-059": {
  "c": "傷無須住院治療不屬8小時內通報，其餘死亡或重傷皆屬重大災害通報對象。",
  "w": {
   "1": "罹災1人需住院屬通報。",
   "2": "死亡災害為8小時通報。",
   "3": "罹災3人以上為8小時通報。"
  },
  "ref": "職業安全衛生法§第37條",
  "law": "《職業安全衛生法》第37條：事業單位工作場所發生職業災害，雇主應即採取必要之急救、搶救等措施，並會同勞工代表實施調查、分析及作成紀錄。\n\n事業單位勞動場所發生下列職業災害之一者，雇主應於八小時內通報勞動檢查機構：\n\n一、發生死亡災害。\n\n二、發生災害之罹災人數在三人以上。\n\n三、發生災害之罹災人數在一人以上，且需住院治療。\n\n四、其他經中央主管機關指定公告之災害。\n\n勞動檢查機構接獲前項報告後，應就工作場所發生死亡或重傷之災害派員檢查。\n\n事業單位發生第二項之災害，除必要之急救、搶救外，雇主非經司法機關或勞動檢查機構許可，不得移動或破壞現場。",
  "g": 1
 },
