  "ref": "營業秘密法§第3條",
  "law": "《營業秘密法》第3條：受雇人於職務上研究或開發之營業秘密，歸雇用人所有。但契約另有約定者，從其約定。\n\n受雇人於非職務上研究或開發之營業秘密，歸受雇人所有。但其營業秘密係利用雇用人之資源或經驗者，雇用人得於支付合理報酬後，於該事業使用其營業秘密。",
